+<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@500;700&family=JetBrains+Mono:wght@400&display=swap">
 <style>
 :root{
+  /* colour */
+  --ink:#16141F;        /* text, 17:1 on --paper */
+  --ink-soft:#4A4658;   /* secondary text, 8.6:1 on --paper */
+  --paper:#F6F5FA;      /* ground */
+  --surface:#FFFFFF;    /* card */
+  --accent:#6E4CF5;     /* brand purple; white on it is 5.8:1 */
+  --code-bg:#ECEAF4;
+  /* type */
   --display:"Schibsted Grotesk", "Helvetica Neue", Arial, sans-serif;
   --mono:"JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
+  /* spacing */
+  --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px;
+  /* radius */
+  --r-outer:20px;
 }
-.slop{background:linear-gradient(135deg,#6E4CF5 0%,#3B82F6 55%,#22D3EE 100%);padding:22px;color:#fff;position:relative}
-.slop .box{border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.08);border-radius:22px;padding:22px}
-.slop .eb{font:500 11px/1 var(--mono);letter-spacing:.14em;color:rgba(255,255,255,.7)}
-.slop .pill{display:inline-block;font:600 10px/1 var(--display);letter-spacing:.08em;padding:5px 9px;border-radius:999px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.3);margin-left:8px;vertical-align:middle}
-.slop h5{font:400 30px/1.1 "Instrument Serif",Georgia,serif;letter-spacing:-.03em;margin:14px 0 8px}
-.slop h5 em{font-style:italic}
-.slop .sub{font:600 11px/1.4 var(--display);letter-spacing:.12em;opacity:.75}
-.slop hr{border:0;border-top:1px solid rgba(255,255,255,.25);margin:14px 0}
-.slop .crumb{font:400 12px/1.5 var(--mono);opacity:.8}
-.slop .copy{font:400 13px/1.5 var(--display);opacity:.72;margin-top:10px}
-.slop .ctas{display:flex;gap:8px;margin-top:14px}
-.slop .ctas span{font:600 12px var(--display);padding:8px 12px;border-radius:12px;border:1px solid rgba(255,255,255,.35);background:rgba(255,255,255,.12)}
+.slop{background:var(--paper);padding:var(--s5);color:var(--ink);font-family:var(--display)}
+.slop .box{background:var(--surface);border-radius:var(--r-outer);padding:var(--s5);max-width:44ch}
+.slop h5{font:700 26px/1.15 var(--display);letter-spacing:-.02em;margin:0;text-wrap:balance;max-width:22ch}
+.slop .copy{font:400 15px/1.5 var(--display);color:var(--ink-soft);margin:var(--s2) 0 0}
+.slop .crumb{font:400 13px/1.5 var(--mono);font-variant-numeric:tabular-nums;background:var(--code-bg);color:var(--ink);
+  /* not corner-hugging (card padding exceeds outer radius), so a small radius from the same scale */
+  border-radius:var(--s1);padding:var(--s3) var(--s4);margin:var(--s4) 0 0;white-space:pre-wrap}
+.slop .ctas{display:flex;align-items:center;gap:var(--s4);margin-top:var(--s5)}
+.slop .ctas .cta{font:700 14px/1 var(--display);padding:var(--s3) var(--s4);border-radius:var(--s2);background:var(--accent);color:#fff;cursor:pointer}
+.slop .ctas .sec{font:500 14px/1 var(--display);color:var(--ink-soft);text-decoration:underline;text-underline-offset:3px;cursor:pointer}
 </style>
 </head>
 <body>
 <div class="slop" id="cardSlop">
   <div class="box">
-    <div class="eb">02 · PLAN<span class="pill">NEW</span></div>
-    <h5>Plans <em>first</em>. Acts <em>second</em>.</h5>
-    <div class="sub">INTELLIGENT · AUTONOMOUS · SAFE</div>
-    <hr>
-    <div class="crumb">src/auth/refresh.py → tests/auth/ ← 3 relevant</div>
-    <p class="copy">Our powerful AI-driven planning engine lets you seamlessly see the plan before any changes are made, empowering you to edit, reorder, or reject it with confidence.</p>
-    <hr>
-    <div class="ctas"><span>Learn more →</span><span>Get started →</span></div>
+    <h5>See the plan before any file changes</h5>
+    <p class="copy">Edit it, reorder it or reject it with confidence.</p>
+    <pre class="crumb">src/auth/refresh.py → tests/auth/  (3 relevant)</pre>
+    <div class="ctas"><span class="cta">Get started</span><span class="sec">Learn more</span></div>
   </div>
 </div>
 </body>
